#include "stdlib/blas/base/cdotc.h"
#include "stdlib/complex/float32/ctor.h"
#include "stdlib/complex/float32/real.h"
#include "stdlib/complex/float32/imag.h"
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define ITERATIONS 1000000

/**
* Benchmarks the cdotc function.
*
* @param len - array length
* @return elapsed time in seconds
*/
double benchmark( int len ) {
	stdlib_complex64_t *x;
	stdlib_complex64_t *y;
	stdlib_complex64_t dot;
	clock_t start;
	clock_t end;
	double t;
	int i;

	x = (stdlib_complex64_t *)malloc( len * sizeof( stdlib_complex64_t ) );
	y = (stdlib_complex64_t *)malloc( len * sizeof( stdlib_complex64_t ) );

	for ( i = 0; i < len; i++ ) {
		x[ i ] = stdlib_complex64_from_real( (float)i );
		y[ i ] = stdlib_complex64_from_real( (float)(len - i) );
	}

	start = clock();
	for ( i = 0; i < ITERATIONS; i++ ) {
		dot = c_cdotc( len, (void *)x, 1, (void *)y, 1 );
	}
	end = clock();

	t = (double)(end - start) / (double)CLOCKS_PER_SEC;

	free( x );
	free( y );

	return t;
}

int main( void ) {
	int len;
	int i;

	printf( "Benchmarking cdotc...\n" );

	for ( i = 1; i <= 6; i++ ) {
		len = 1;
		len <<= i;
		printf( "len=%d: %f seconds\n", len, benchmark( len ) );
	}

	return 0;
}